/// Runs JavaScript jobs in a QuickJS runtime with full tool bridge support.
///
/// Phase 4 orchestrator — mirrors the Java `JobJavaScriptBridge` /
/// `JavaScriptExecutor` pipeline:
/// 1. Create a QuickJS runtime.
/// 2. Inject job context (`params.jobParams`, `params.ticket`, …).
/// 3. Install the CommonJS `require` loader ([installRequireLoader]).
/// 4. Generate and eval snake_case tool wrapper JS for every tool.
/// 5. Register host functions (`executeToolViaJava`, `file_read`,
///    `set_env_variable`, `console`) via [ToolBridge] — last, so the direct
///    `file_read` global wins over the generated wrapper.
/// 6. Set the current script directory (relative `require` base), load the
///    script source (file / inline / URL — Java `loadJavaScriptCode`
///    parity), and eval it.
/// 7. Call the script's `action(params)` — the JSRunner contract. Scripts
///    without an `action` function fail with the Java-parity error
///    `JavaScript code must define an 'action' function`.
library;

import 'dart:convert';
import 'dart:io';

import '../mcp/default_tool_registry.dart';
import '../mcp/tool_registry.dart';
import 'package:quickjs_runtime/quickjs_runtime.dart';
import 'async_job_pool.dart';
import 'engine_factory.dart';
import 'sync_http_client.dart';

/// Optional configuration for [JsJobRunner.runScript].
///
/// Bundles the less-commonly-used parameters so that [JsJobRunner.runScript]
/// stays within the quality-gate param limit.
class JsRunConfig {
  /// Creates a run configuration.
  const JsRunConfig({
    this.integrationFilter,
    this.registry,
    this.extraGlobals,
    this.contextParams,
    this.pool,
    this.httpFetch,
    this.consolePrefix,
    this.preActionCode,
  });

  /// Restricts generated wrappers to the named integrations.
  ///
  /// When null, wrappers for all integrations are generated.
  final Set<String>? integrationFilter;

  /// Tool registry to use; defaults to the full catalog when null.
  final ToolRegistry? registry;

  /// Additional top-level JS globals set after `params` but before the
  /// script runs.
  final Map<String, dynamic>? extraGlobals;

  /// Additional entries merged into the `params` object passed to
  /// `action(params)` — mirrors Java `JavaScriptExecutor.withJobContext()` /
  /// `.with()` bindings (`response`, `initiator`, `inputJql`, `metadata`, …).
  ///
  /// Null-valued entries must be omitted by the caller (Java's
  /// `JSONObject.put(key, null)` removes the key).
  final Map<String, dynamic>? contextParams;

  /// Worker pool for `runAsync(fn, args)` (defaults to
  /// [AsyncJobPool.instance]). Only consulted when `jobParams` carries
  /// `parallelWorkers >= 2`. The CLI dispatcher boots the pool it passes
  /// here (gh-241: the shared instance, lazily, just before the JS run);
  /// tests boot a private pool and pass it here.
  final AsyncJobPool? pool;

  /// Alternate `fetch` transport for the node/js compat layer on the
  /// main engine (JSON in, JSON out). Defaults to the pooled
  /// [SyncHttpClient]; see [EngineSpec.httpFetch].
  final String? Function(String requestJson)? httpFetch;

  /// Prefix prepended to every `console.*` line the script prints —
  /// shard/worker log attribution (mirrors [EngineSpec.consolePrefix],
  /// used by the sharded agents-suite runner). Null keeps the default
  /// unprefixed console output.
  final String? consolePrefix;

  /// JS evaluated in the same context AFTER the script source but
  /// BEFORE `action(params)` — a host-side hook to prime or mutate the
  /// script's globals (the sharded agents suite uses it to neutralize
  /// `testRunner.js` counting while a shard evals its prime prefix; see
  /// `agents_suite.dart`). Null (default) keeps the plain
  /// eval-then-action pipeline.
  final String? preActionCode;
}

/// A resolved script source: the [code] plus the [filename] used for eval
/// diagnostics.
class _LoadedScript {
  const _LoadedScript(this.code, this.filename);

  /// Inline code: the source itself is the "path", so eval diagnostics
  /// get a stable pseudo-filename.
  const _LoadedScript.inline(String code) : this(code, '<inline>');

  final String code;
  final String filename;
}

/// Runs JavaScript agent/test scripts in a QuickJS runtime.
class JsJobRunner {
  /// Creates a new job runner.
  const JsJobRunner();

  /// Runs [scriptPath] as a JS job with the given [jobParams].
  ///
  /// Mirrors the Java `JobJavaScriptBridge.executeJavaScript` contract:
  /// the script source is resolved via `loadJavaScriptCode` parity (file,
  /// inline code, or http(s) URL), evaluated, and its `action(params)`
  /// function is invoked — scripts without `action` fail with the
  /// Java-parity error. The action's return value (JSON) is the result;
  /// `null` means JS `undefined`.
  ///
  /// - [jobParams] — injected as `params.jobParams` in the JS global scope.
  /// - [ticket] — injected as `params.ticket` when non-null.
  /// - [workingDirectory] — base for relative file paths in tool calls.
  /// - [config] — optional [JsRunConfig] for integration filtering, custom
  ///   registries, and extra JS globals / params context.
  String? runScript({
    required String scriptPath,
    required Map<String, dynamic> jobParams,
    Map<String, dynamic>? ticket,
    String? workingDirectory,
    JsRunConfig? config,
  }) {
    final cfg = config ?? const JsRunConfig();
    final rt = QuickjsRuntime();
    try {
      final reg = cfg.registry ?? createDefaultToolRegistry();
      final compat =
          _wireRuntime(rt, reg, jobParams, ticket, workingDirectory, cfg);
      if (JsJobRunner.needsAsyncPool(jobParams)) {
        _wireAsyncPool(
          rt,
          scriptPath: scriptPath,
          jobParams: jobParams,
          ticket: ticket,
          workingDirectory: workingDirectory,
          cfg: cfg,
        );
      }
      setScriptDirectory(rt, scriptPath);
      final loaded = _loadJavaScriptCode(scriptPath);
      _evalScript(rt, loaded.code, loaded.filename);
      if (cfg.preActionCode != null) {
        _evalScript(rt, cfg.preActionCode!, '<pre_action>');
      }
      final result = _callAction(rt);
      // nodeCompat scripts may register timers (setTimeout-as-sleep etc.);
      // block-mode drain (dmtools default) settles them like Node would.
      // DRAIN-ERROR POLICY (epam/dmtools-dart#243): the MAIN engine
      // deliberately propagates a drain failure — for a script the timer
      // chain IS part of the run's contract (side-effect timers, sleep
      // pattern), and silently dropping callbacks would report success
      // with lost effects. Worker dispatches swallow-with-a-log instead
      // (async_job_pool.dart): there the fn's return value is the job.
      compat?.drainTimers();
      return result;
    } finally {
      rt.close();
    }
  }

  /// Whether [jobParams] enable the `runAsync` engine-worker surface —
  /// the single source of the `parallelWorkers >= 2` predicate, shared by
  /// [runScript] (pool wiring) and the CLI dispatcher (lazy pool boot,
  /// epam/dmtools-dart#241).
  static bool needsAsyncPool(Map<String, dynamic> jobParams) =>
      effectiveParallelWorkers(jobParams) >= 2;

  /// Effective `parallelWorkers` knob (0 when absent or non-numeric).
  ///
  /// Values >= 2 enable the `runAsync` API on the engine; everything else
  /// keeps the default sequential surface (default-off, zero deviation).
  static int effectiveParallelWorkers(Map<String, dynamic> jobParams) {
    final value = jobParams['parallelWorkers'];
    return value is num ? value.toInt() : 0;
  }

  /// Wires the `runAsync` / `AsyncJob` surface onto [rt] by delegating
  /// to [AsyncJobPool.attachMainRuntime] (quickjs_runtime owns the
  /// `__jsr*` host functions and the prelude — no adapter duplicate,
  /// epam/dmtools-dart#242).
  ///
  /// Uses [JsRunConfig.pool], defaulting to [AsyncJobPool.instance]. When
  /// the pool is not booted, `runAsync(...)` throws a clear JS error on
  /// first use (dispatch sentinel) instead of failing the engine wiring.
  void _wireAsyncPool(
    QuickjsRuntime rt, {
    required String scriptPath,
    required Map<String, dynamic> jobParams,
    required Map<String, dynamic>? ticket,
    required String? workingDirectory,
    required JsRunConfig cfg,
  }) {
    final pool = cfg.pool ?? AsyncJobPool.instance;
    final params = buildParamsMap(
      jobParams: jobParams,
      ticket: ticket,
      contextParams: cfg.contextParams,
      extraGlobals: cfg.extraGlobals,
    );
    pool.attachMainRuntime(
      rt,
      scriptDirectory: jsDirectoryOf(scriptPath),
      workingDirectory: workingDirectory,
      params: params,
    );
  }

  /// Evaluates the script source, surfacing JS exceptions.
  ///
  /// QuickJS reports eval exceptions through `errMsg` (the eval itself
  /// returns `null`); Java wraps the same failure in
  /// `RuntimeException("JavaScript execution failed: …")` — mirrored here.
  void _evalScript(QuickjsRuntime rt, String code, String filename) {
    final errors = <String?>[];
    rt.eval(code, filename: filename, errMsg: errors);
    if (errors.isNotEmpty) {
      throw StateError('JavaScript execution failed: ${errors.first}');
    }
  }

  /// Invokes the script's `action(params)` (JSRunner contract).
  ///
  /// Missing / non-function `action` fails with the Java-parity message;
  /// exceptions raised inside `action` surface as evaluation failures.
  String? _callAction(QuickjsRuntime rt) {
    final kind = rt.eval('typeof action', filename: '<action_check>');
    if (jsonDecode(kind ?? '"undefined"') != 'function') {
      throw StateError("JavaScript code must define an 'action' function");
    }
    final errors = <String?>[];
    final result = rt.eval(
      'action(params)',
      filename: '<action_call>',
      errMsg: errors,
    );
    if (errors.isNotEmpty) {
      throw StateError('JavaScript execution failed: ${errors.first}');
    }
    return result;
  }

  /// Wires up job context, require loader, tool wrappers, and host
  /// functions on [rt].
  ///
  /// Delegates to [wireEngine] — the shared wiring used verbatim by the
  /// `runAsync` worker engines, so both paths stay behaviorally identical.
  /// Host functions are registered **after** the generated tool wrappers so
  /// that the direct `file_read` global (returning the raw content string,
  /// as testRunner.js requires) takes precedence over the wrapper that
  /// dispatches through `executeToolViaJava` with an `{content: …}` shape.
  NodeCompatHandle? _wireRuntime(
    QuickjsRuntime rt,
    ToolRegistry registry,
    Map<String, dynamic> jobParams,
    Map<String, dynamic>? ticket,
    String? workingDirectory,
    JsRunConfig config,
  ) {
    return wireEngine(
      rt,
      EngineSpec(
        context: EngineContext(
          jobParams: jobParams,
          ticket: ticket,
          contextParams: config.contextParams,
          extraGlobals: config.extraGlobals,
        ),
        registry: registry,
        integrationFilter: config.integrationFilter,
        workingDirectory: workingDirectory,
        httpFetch: config.httpFetch,
        consolePrefix: config.consolePrefix,
      ),
    );
  }

  // ── Script source resolution (Java loadJavaScriptCode parity) ─────────

  /// Resolves [jsSourceOrPath] to script code — Java
  /// `JobJavaScriptBridge.loadJavaScriptCode` parity:
  /// http(s) URLs fetch remotely; inline code (starts with `function` or
  /// contains `action`) and strings without `/` / `.js` pass through
  /// as-is; everything else loads from the filesystem.
  _LoadedScript _loadJavaScriptCode(String jsSourceOrPath) {
    if (jsSourceOrPath.startsWith('http://') ||
        jsSourceOrPath.startsWith('https://')) {
      return _LoadedScript(
        _loadFromUrl(jsSourceOrPath),
        jsSourceOrPath,
      );
    }
    final isInline = jsSourceOrPath.trim().startsWith('function') ||
        jsSourceOrPath.contains('action') ||
        (!jsSourceOrPath.contains('/') && !jsSourceOrPath.endsWith('.js'));
    if (isInline) return _LoadedScript.inline(jsSourceOrPath);
    return _LoadedScript(_loadFromFile(jsSourceOrPath), jsSourceOrPath);
  }

  /// Loads script code from the filesystem, or fails with the Java-parity
  /// `JavaScript file not found` message.
  String _loadFromFile(String path) {
    try {
      return File(path).readAsStringSync();
    } on FileSystemException {
      throw StateError(
        'JavaScript file not found in resources or filesystem: $path',
      );
    }
  }

  /// Synchronously fetches [url] via [SyncHttpClient] (curl subprocess).
  String _loadFromUrl(String url) {
    final response = SyncHttpClient.get(url);
    if (!response.isOk) {
      throw StateError(
        'Failed to load JS from source code: $url '
        '(HTTP ${response.statusCode}: ${response.body})',
      );
    }
    return response.body;
  }
}
/// Pre-spawned engine-worker pool behind `runAsync(fn, args)` — parallel
/// JavaScript execution over the synchronous QuickJS bridge
/// (epam/dmtools-dart#224, Option A).
///
/// The transport and lifecycle mechanics live in the `quickjs_runtime`
/// package ([AsyncEnginePool]): worker spawning + handshake, the
/// dispatch/wait mailbox protocol, FIFO backpressure, fire-and-forget
/// envelope caching, and dead-worker completion. This file is the
/// dmtools adapter on top:
///
/// - the worker body ([_dmtoolsWorkerMain], a top-level `Isolate.spawn`
///   entry): per-worker `SyncHttpBridge` (statics are per-isolate, so the
///   worker's HTTP calls never interleave with the main engine's) and a
///   fresh, fully wired engine per job — own tool registry, own require
///   cache ([wireEngine]/[EngineSpec]);
/// - the per-dispatch context: params/working-directory/script-directory
///   of the calling engine run plus a [PropertyReader] overrides snapshot
///   (mirrors Java ThreadLocal overrides), captured through the
///   `quickjs_runtime` per-runtime `dispatchContext` provider
///   ([AsyncJobPool.attachMainRuntime]; epam/dmtools-dart#242);
///
/// Each worker is a full parallel engine on its own isolate. QuickJS
/// engines are never shared across isolates — one engine per isolate,
/// always.
///
/// Boot discipline: spawning must complete while the event loop is alive
/// (`Isolate.spawn` cannot progress once the spawning isolate is blocked
/// in an FFI callback) and before the job's JS runs. The CLI satisfies it
/// by booting [instance] lazily in `CliDispatcher`, just before a job
/// whose resolved config sets `parallelWorkers >= 2` — every other
/// command pays nothing (epam/dmtools-dart#241). Tests boot private pools
/// and must call [dispose] in teardown.
///
/// No timeouts in v1: a dispatched function that never returns blocks its
/// caller forever, exactly like a main-script infinite loop would. See
/// the `quickjs_runtime` `async_engine_pool` docs for the remaining
/// failure-path semantics (dead workers complete their unwaited jobs with
/// an error envelope).
library;

import 'dart:io';

import 'package:quickjs_runtime/quickjs_runtime.dart';

import '../config/property_reader.dart';
import 'engine_factory.dart';
import 'sync_http_bridge.dart';

export 'package:quickjs_runtime/quickjs_runtime.dart' show AsyncJobEnvelope;

/// Worker body: warm per-worker HTTP bridge, fresh wired engine per job.
///
/// Top-level on purpose — an `Isolate.spawn` entry cannot capture
/// instance state. Never throws: every job is answered with an envelope.
Future<void> _dmtoolsWorkerMain(AsyncWorkerLink link) async {
  await SyncHttpBridge.shared.boot();
  try {
    while (true) {
      final request = await link.next();
      if (request == null) return; // shutdown
      try {
        link.complete(
          AsyncJobEnvelope.fromJson(_runJobOnWorker(link.workerId, request)),
        );
      } catch (e) {
        // Last-resort: the caller is parked in a blocking Mailbox.take()
        // with its event loop frozen — a throw past this point kills the
        // worker mid-job and hangs that caller forever (the dead-worker
        // exit listener can never run while the loop is frozen). Answer
        // every request, no matter what broke inside the job.
        link.complete(
          AsyncJobEnvelope(
            jobId: request.jobId,
            ok: false,
            error: 'worker job failed unexpectedly: $e',
          ),
        );
      }
    }
  } finally {
    SyncHttpBridge.shared.dispose(); // this isolate's private HTTP worker
  }
}

/// Runs one dispatched function on a fresh engine — never throws.
Map<String, dynamic> _runJobOnWorker(int workerId, AsyncJobRequest request) {
  // Engine boot (e.g. the QuickJS dylib dlopen) must stay INSIDE the try:
  // a throw past it kills the worker isolate without answering the job,
  // and the caller is parked in a blocking Mailbox.take() with the event
  // loop frozen — nothing can ever complete that wait.
  QuickjsRuntime? runtime;
  try {
    final overrides = request.context['overrides'];
    PropertyReader.setOverrides(
      overrides is Map
          ? overrides.map((k, v) => MapEntry('$k', '$v'))
          : <String, String>{},
    );
    runtime = QuickjsRuntime();
    final compat = wireEngine(
      runtime,
      EngineSpec(
        context: EngineContext.direct(
          request.context['params'] as Map<String, dynamic>,
        ),
        workingDirectory: request.context['workingDirectory'] as String?,
        scriptDirectory: request.context['scriptDirectory'] as String?,
        consolePrefix: '[jsr:$workerId] ',
      ),
    );
    final result = runAsyncJobOnRuntime(
      runtime,
      jobId: request.jobId,
      fnSource: request.fnSource,
      argsJson: request.argsJson,
    );
    // dispatched fns can register timers; drain them once the job settles.
    // DRAIN-ERROR POLICY (epam/dmtools-dart#243): a worker swallows a drain
    // failure — with a log line — because the dispatched function's own
    // result/error IS the job and must not be masked by a late timer
    // callback. The MAIN engine deliberately propagates instead (see
    // JsJobRunner): there the timer chain is part of the run's contract.
    try {
      compat?.drainTimers();
    } catch (e) {
      stderr.writeln('[jsr:$workerId] timer drain failed (envelope '
          'unchanged): $e');
    }
    return result;
  } catch (e) {
    return AsyncJobEnvelope(
      jobId: request.jobId,
      ok: false,
      error: e.toString(),
    ).toJson();
  } finally {
    runtime?.close();
  }
}

/// dmtools pool: [AsyncEnginePool] wired with the dmtools worker body.
///
/// The CLI uses [instance]; tests create private pools and must call
/// [dispose] in teardown so the isolates exit and the test runner ends.
class AsyncJobPool {
  /// Creates a pool that [boot]s [workers] engine isolates.
  AsyncJobPool({this.workers = defaultWorkerCount})
      : _pool = AsyncEnginePool(
          workers: workers,
          workerMain: _dmtoolsWorkerMain,
        );

  /// Default worker count for the CLI pool.
  static const int defaultWorkerCount = 4;

  /// Process-wide pool used by the CLI — booted lazily by `CliDispatcher`
  /// when a job enables `runAsync` (epam/dmtools-dart#241).
  static final AsyncJobPool instance = AsyncJobPool();

  /// Number of engine isolates this pool boots.
  final int workers;

  final AsyncEnginePool _pool;

  /// Whether [dispatch] is usable.
  bool get ready => _pool.ready;

  /// Boots the worker isolates; idempotent. Must run while the event loop
  /// is alive.
  Future<void> boot() => _pool.boot();

  /// Dispatches one job to a worker and returns its id.
  ///
  /// Blocks while every worker is busy (FIFO backpressure) or while the
  /// first worker finishes booting. Never called with an unbooted pool by
  /// production wiring: `JsJobRunner` checks [ready] via the `runAsync`
  /// prelude contract and surfaces a JS error instead.
  int dispatch({
    required String fnSource,
    required String argsJson,
    required String scriptDirectory,
    String? workingDirectory,
    required Map<String, dynamic> params,
    Map<String, String> overrides = const {},
  }) {
    return _pool.dispatch(
      fnSource: fnSource,
      argsJson: argsJson,
      context: {
        'scriptDirectory': scriptDirectory,
        'workingDirectory': workingDirectory,
        'params': params,
        'overrides': overrides,
      },
    );
  }

  /// Waits for [jobId] and returns its envelope (blocking).
  ///
  /// Serving from cache makes a late `wait()` on an already-completed
  /// fire-and-forget job work. Waiting twice for the same job throws.
  AsyncJobEnvelope wait(int jobId) => _pool.wait(jobId);

  /// Wires the `runAsync` / `AsyncJob` surface onto [runtime] — full
  /// delegation to `quickjs_runtime` (host functions + prelude), no
  /// adapter-owned `__jsr*` duplicate (epam/dmtools-dart#242; needs the
  /// per-runtime `dispatchContext` from quickjs_runtime 0.3.4).
  ///
  /// The dispatch context provider runs synchronously inside the
  /// `runAsync` host call: it snapshots [scriptDirectory],
  /// [workingDirectory], the composed [params] map and the CURRENT
  /// [PropertyReader] overrides (Java ThreadLocal overrides parity) at
  /// dispatch time — exactly the snapshot the deleted
  /// `dispatchAsyncJob` used to build inline.
  void attachMainRuntime(
    QuickjsRuntime runtime, {
    required String scriptDirectory,
    String? workingDirectory,
    required Map<String, dynamic> params,
  }) {
    _pool.attachMainRuntime(
      runtime,
      dispatchContext: () => {
        'scriptDirectory': scriptDirectory,
        'workingDirectory': workingDirectory,
        'params': params,
        'overrides': PropertyReader.getOverrides(),
      },
    );
  }

  /// Asks every worker to exit (in-flight jobs finish first) and resets
  /// the pool; a fresh [boot] revives it.
  void dispose() => _pool.dispose();

  /// Kills a worker isolate outright (dead-worker test hook).
  ///
  /// `Isolate.beforeNextEvent` lets the worker unwind — its private HTTP
  /// bridge is disposed by the worker's own `finally`, so the test VM does
  /// not leak the child isolate.
  void killWorkerForTest(int workerId) => _pool.killWorkerForTest(workerId);
}

