    if (path is! String) {
      return _stripMeta(child);
    }
    final loaded = _loadAndResolve(path, configDir);
    final overridePaths = _readStringList(child, 'override');
    final mergePaths = _readStringList(child, 'merge');
    final strippedChild = _stripMeta(child);
