  }) {
    final file = File(path);
    if (!file.existsSync()) {
      throw ArgumentError('Config file not found: $path');
    }
    final raw = file.readAsStringSync();
    var config = jsonDecode(raw) as Map<String, dynamic>;
    config = _ParentConfigResolver(packResolver: _packResolver)
