      final reg = cfg.registry ?? createDefaultToolRegistry();
      final compat =
          _wireRuntime(rt, reg, jobParams, ticket, workingDirectory, cfg);
      if (JsJobRunner.needsAsyncPool(jobParams)) {
        _wireAsyncPool(
          rt,
          scriptPath: scriptPath,
          jobParams: jobParams,
          ticket: ticket,
          workingDirectory: workingDirectory,
          cfg: cfg,
