    registry: registry,
    workingDirectory: spec.workingDirectory,
    consolePrefix: spec.consolePrefix,
  );
  bridge.registerHostFunctions(rt);
  installRequireLoader(rt);
  rt.eval(
    buildWrapperSource(registry, spec.integrationFilter),
    filename: '<tool_wrappers>',
  );
